/**
 * Tests for no-insecure-ssl
 * CWE-319 — Prevent the use of insecure SSL configurations (rejectUnauthorized: false).
 *
 * Generated by: node scripts/generate-rule-tests.mjs
 * Standard: Engineering Standards §5 (side-by-side), §6 (≥5 valid + ≥5 invalid), §8 (RuleTester at describe level)
 */
import { RuleTester } from '@typescript-eslint/rule-tester';
import { describe, it, afterAll } from 'vitest';
import parser from '@typescript-eslint/parser';
import { noInsecureSsl } from './index';

/**
 * Every fixture imports a PostgreSQL client, because the rule now abstains in
 * files that use no PostgreSQL at all. Wrapping the arrays rather than editing
 * each fixture means one cannot be left behind — a fixture missing the import
 * would pass vacuously on the gate instead of exercising the detection it was
 * written for.
 */
const withPg = (code: string): string => `import { Pool } from 'pg';\n${code}`;
const pg = <T,>(cases: T[]): T[] =>
  cases.map((c) =>
    typeof c === 'string'
      ? (withPg(c) as T)
      : ({ ...c, code: withPg((c as { code: string }).code) } as T),
  );


RuleTester.afterAll = afterAll;
RuleTester.it = it;
RuleTester.itOnly = it.only;
RuleTester.describe = describe;

const ruleTester = new RuleTester({
  languageOptions: {
    parser,
    ecmaVersion: 2022,
    sourceType: 'module',
    parserOptions: { ecmaFeatures: { jsx: true } },
  },
});

describe('no-insecure-ssl', () => {
  describe('Valid Code', () => {
    ruleTester.run('valid - safe patterns', noInsecureSsl, {
      valid: pg([
        // Unrelated code should not trigger
        {
          code: `const x = 1;`,
        },
        // Array operations are safe
        {
          code: `const arr = [1, 2, 3];`,
        },
        // Static property values are safe
        {
          code: `const config = { key: "static-value" };`,
        },
        // Environment variable usage is safe (padding case 4)
        {
          code: `const safe3 = process.env.DB_HOST;`,
        },
        // Environment variable usage is safe (padding case 5)
        {
          code: `const safe4 = process.env.DB_HOST;`,
        },
      ]),
      invalid: [],
    });
  });

  describe('Invalid Code', () => {
    ruleTester.run('invalid - dangerous patterns', noInsecureSsl, {
      valid: [],
      invalid: pg([
        // Triggers noInsecureSsl: rejectUnauthorized disabled in SSL config.
        //
        // This fixture used to read `new Client({...})` with NOTHING named
        // `Client` imported anywhere in it, and it passed — because the rule
        // decided from the SPELLING of the callee. It was a test asserting the
        // defect as correct behaviour. The import is what makes it a Client.
        {
          code: `import { Client } from 'pg';\nnew Client({ host: 'db.example.com', ssl: { rejectUnauthorized: false } })`,
          errors: [{ messageId: 'noInsecureSsl' }],
        },
      ]),
    });
  });

  /**
   * Regression locks for the defects
   * `benchmarks/rule-corpus/postgresql-security__no-insecure-ssl` proved.
   * Each `invalid` case was SILENT on the shipped rule; each `valid` case was
   * REPORTED by it.
   */
  describe('corpus regressions', () => {
    ruleTester.run('the callee is resolved, not spelled', noInsecureSsl, {
      valid: pg([
        // FP — a `Pool` from `generic-pool` is not a PostgreSQL pool, however
        // it is spelled. This was reported.
        "import { Pool as WorkerPool } from 'generic-pool';\nnew WorkerPool({ ssl: { rejectUnauthorized: false } });",
        // An `ioredis` client with the identically-spelled option.
        "import Redis from 'ioredis';\nnew Redis({ tls: { rejectUnauthorized: false } });",
        // A constructor this file never imported at all.
        'new Client({ ssl: { rejectUnauthorized: false } });',
        // A `new` on a locally declared class, not a module binding.
        'class LocalPool {}\nnew LocalPool({ ssl: { rejectUnauthorized: false } });',
        // A computed key that is not a static string names nothing knowable.
        'new Pool({ [KEY]: { rejectUnauthorized: false } });',
        // More binding hops than the walker follows.
        'const a = { ssl: { rejectUnauthorized: false } };\nconst b = a;\nconst c = b;\nconst d = c;\nconst e = d;\nconst f = e;\nnew Pool(f);',
        // A parameter has no initialiser to follow.
        'export function make(config) { return new Pool(config); }',
        // Declared without an initialiser.
        'let config;\nnew Pool(config);',
        // Declared without an initialiser, then assigned once — there is a
        // declaration to find but nothing on it to follow.
        'let config;\nconfig = loadConfig();\nnew Pool(config);',
        // A PARAMETER assigned once inside the body: written exactly once, but
        // the definition is not a declaration and carries no initialiser.
        'export function make(config) { config = { ssl: { rejectUnauthorized: false } }; return new Pool(config); }',
      ]),
      invalid: [
        // FN — `new pg.Pool(...)`, the namespace spelling. The callee is a
        // MemberExpression with no `.name`, so the rule never looked at it.
        {
          code: "const pg = require('pg');\nnew pg.Pool({ ssl: { rejectUnauthorized: false } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        {
          code: "import pg from 'pg';\nnew pg.Client({ ssl: { rejectUnauthorized: false } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // The module itself is the constructor.
        {
          code: "const Pool = require('pg-pool');\nnew Pool({ ssl: { rejectUnauthorized: false } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
      ],
    });

    ruleTester.run('the config is followed one binding hop', noInsecureSsl, {
      valid: pg([
        // Written twice — what reaches the constructor is not knowable.
        'let config = { ssl: { rejectUnauthorized: false } };\nconfig = strict;\nnew Pool(config);',
        // No first argument at all.
        'new Pool();',
        // A config that is neither an object nor a string.
        'new Pool(loadConfig());',
        // No `ssl` key: pg defaults to no TLS, which is a deployment decision.
        "new Pool({ host: 'localhost', database: 'dev' });",
        // An `ssl` value that is not an object literal.
        'new Pool({ ssl: true });',
        'new Pool({ ssl: buildTls() });',
        // No `rejectUnauthorized` key.
        'new Pool({ ssl: { ca: CA } });',
      ]),
      invalid: pg([
        // FN — every real application writes the config one binding away.
        {
          code: 'const config = { ssl: { rejectUnauthorized: false } };\nnew Pool(config);',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        {
          code: 'const tls = { rejectUnauthorized: false };\nnew Pool({ ssl: tls });',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // ES6 shorthand.
        {
          code: 'const ssl = { rejectUnauthorized: false };\nnew Pool({ ssl });',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // A TypeScript cast is erased and changes nothing.
        {
          code: 'const config = { ssl: { rejectUnauthorized: false } } as PoolConfig;\nnew Pool(config);',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
      ]),
    });

    ruleTester.run('the value is folded, not matched', noInsecureSsl, {
      valid: pg([
        'new Pool({ ssl: { rejectUnauthorized: true } });',
        'const VERIFY = true;\nnew Pool({ ssl: { rejectUnauthorized: VERIFY } });',
        // Decided at runtime — the file does not disable verification.
        "new Pool({ ssl: { rejectUnauthorized: process.env.NODE_ENV === 'production' } });",
        // An absent option takes tls.connect's default, which is to verify.
        'new Pool({ ssl: { rejectUnauthorized: undefined } });',
      ]),
      invalid: pg([
        // FN — hoisting the value into a named constant reads as MORE careful,
        // and turned the finding off.
        {
          code: 'const VERIFY_CERTIFICATE = false;\nnew Pool({ ssl: { rejectUnauthorized: VERIFY_CERTIFICATE } });',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // FN (adversarial) — Node COERCES the option. Measured: a TLSSocket
        // built with `rejectUnauthorized: 0` reports `_rejectUnauthorized`
        // false, exactly as `false` does.
        {
          code: 'new Pool({ ssl: { rejectUnauthorized: 0 } });',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        {
          code: 'new Pool({ ssl: { rejectUnauthorized: null } });',
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        {
          code: "new Pool({ ssl: { rejectUnauthorized: '' } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // FN (adversarial) — a computed key names the same property, and
        // writing the brackets turned the finding off.
        {
          code: "new Pool({ ['ssl']: { ['rejectUnauthorized']: false } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
      ]),
    });

    // `Client` must be imported to BE a Client — the whole point of the fix
    // above — so these fixtures carry their own import rather than the `Pool`
    // one the `pg()` wrapper adds.
    const withClient = <T,>(cases: T[]): T[] =>
      cases.map((c) =>
        typeof c === 'string'
          ? (`import { Client } from 'pg';\n${c}` as T)
          : ({
              ...c,
              code: `import { Client } from 'pg';\n${(c as { code: string }).code}`,
            } as T),
      );

    ruleTester.run('the DSN spelling of the same defect', noInsecureSsl, {
      valid: withClient([
        "new Client({ connectionString: 'postgres://app@h:5432/db?sslmode=verify-full' });",
        "new Client({ connectionString: 'postgres://app@h:5432/db' });",
        "new Client('postgres://app@h:5432/db');",
        'new Client({ connectionString: process.env.DATABASE_URL });',
        // A non-string first argument that is not an object either.
        'new Client(42);',
      ]),
      invalid: withClient([
        // FN — libpq's spelling of rejectUnauthorized:false, and the one that
        // survives review because it looks like configuration.
        {
          code: "new Client({ connectionString: 'postgres://app@h:5432/db?sslmode=no-verify' });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        {
          code: "new Client('postgres://app@h:5432/db?sslmode=no-verify');",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // Through one binding hop.
        {
          code: "const DSN = 'postgres://app@h:5432/db?sslmode=no-verify';\nnew Client({ connectionString: DSN });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // Case-insensitively, as libpq reads it.
        {
          code: "new Client({ connectionString: 'postgres://h/db?sslmode=NO-VERIFY' });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
        // A DSN that skips verification AND an ssl block: the DSN is reported
        // and the walk stops, so the site is billed once.
        {
          code: "new Client({ connectionString: 'postgres://h/db?sslmode=no-verify', ssl: { rejectUnauthorized: false } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
      ]),
    });

    // NOT wrapped — a file with no PostgreSQL client in it does no work at all.
    ruleTester.run('the module gate still abstains', noInsecureSsl, {
      valid: [
        "import { Pool } from 'generic-pool';\nnew Pool({ ssl: { rejectUnauthorized: false } });",
      ],
      invalid: [],
    });

    ruleTester.run('scoped PostgreSQL packages count too', noInsecureSsl, {
      valid: [],
      invalid: [
        {
          code: "import { Pool } from '@vercel/postgres';\nnew Pool({ ssl: { rejectUnauthorized: false } });",
          errors: [{ messageId: 'noInsecureSsl' }],
        },
      ],
    });
  });
});
